import java.io.*;
import java.util.*;

class Ladder {
    private String type;
    private int price;

    public Ladder() {
    }

    public Ladder(String type, int price) {
        this.type = type;
        this.price = price;
    }

    public String getType() { return type; }
    public int getPrice() { return price; }
    public void setType(String type) { this.type = type; }

    @Override
    public String toString() {
        return type + ", " + price;
    }
}

