import java.io.*;
import java.util.*;

// Stand-in for the given Main.class (javap -c): TC2 prints "%s, %d" from getType()/getPrice(), not toString()
class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        System.out.println();
        System.out.print("Enter type: ");
        String type = sc.nextLine();
        System.out.print("Enter price: ");
        int price = sc.nextInt();
        sc.nextLine();
        System.out.print("Enter weight: ");
        int weight = sc.nextInt();
        sc.nextLine();
        System.out.println("1. Test toString()");
        System.out.println("2. Test setData()");
        System.out.println("3. Test getValue()");
        System.out.print("Enter TC (1,2,3): ");
        int tc = sc.nextInt();
        sc.nextLine();
        System.out.println("OUTPUT:");
        switch (tc) {
            case 1:
                System.out.println(new Ladder(type, price));
                System.out.println(new SpecLadder(type, price, weight));
                break;
            case 2:
                SpecLadder s = new SpecLadder(type, price, weight);
                s.setData();
                System.out.printf("%s, %d\n", s.getType(), s.getPrice());
                break;
            case 3:
                System.out.printf("%s\n", new SpecLadder(type, price, weight).getValue());
                break;
        }
        System.out.println();
    }
}
